({initialize:function(){document.addEventListener("deviceready",this.onDeviceReady.bind(this),!1)},onDeviceReady:function(){window.screen.orientation.lock("landscape-primary"),this.prepareAccelerometer()},prepareAccelerometer:function(){var e=navigator.accelerometer.watchAcceleration(this.accelerometerSuccess,this.accelerometerError,{frequency:300})},accelerometerSuccess:function(e){document.getElementById("accelerationX").innerHTML=parseFloat(Math.round(100*e.x)/100).toFixed(2),document.getElementById("accelerationY").innerHTML=parseFloat(Math.round(100*e.y)/100).toFixed(2),document.getElementById("accelerationZ").innerHTML=parseFloat(Math.round(100*e.z)/100).toFixed(2)},accelerometerError:function(e){alert("onError!")}}).initialize();